    "article": "Diktate sind auch heute noch Bestandteil des Sprachunterrichts an Schulen. Forscher fanden jetzt aber, dass sie weder objektiv benotet werden noch Kindern beim Schreibenlernen helfen.\n\nIn den neuen Bildungsplänen für die Grundschule wurden bereits erste Konsequenzen [1]____. Benotete Diktate sind nicht mehr [2]____.\n\nIn einer Studie haben mehrere hundert Lehrer das gleiche Diktat bewertet und in demselben Text zwischen zwei und elf Fehler gefunden. Auch die Note [3]____, und zwar zwischen 2 und 5.\n\nKlassendiktate sind lernpsychologisch ungünstig, weil sich immer dasselbe wiederholt. Kinder, die stressempfindlich sind, die keine Unterstützung von zu Hause [4]____, sind die Verlierer. Sie kommen mit dem Zeitdruck nicht [5]____. Insofern sind Diktate sehr belastend für immer dieselben Kinder und bestätigen dem Lehrer nur, was er schon weiß.\n\nHinzu kommt: Bei der Bewertung zählen Lehrer die falschen Wörter und nicht nur [6]____ Rechtschreibthema. Dennoch gibt es sinnvolle Alternativen [7]____ klassischen Diktat. Wenn Lehrer sie nutzen, [8]____ analysieren, wo die Kinder Schwierigkeiten haben, oder wenn Kinder in Partnerdiktaten bestimmte Wörter üben, ist dies [9]____ sinnvoll.\n\nBefürworter von Diktaten [10]____, die Kinder könnten während [11]____ durch das Zuhören lernen. Aber man muss konstatieren, dass sie Rechtschreibung [12]____ durch Zuhören lernen. Es gibt Lehrer, die den diktierten Text ganz deutlich artikulieren, [13]____, dass die Kinder die Wörter dann richtig schreiben würden.\n\nAber unsere Schrift ist kein [14]____ der Artikulation: Den Unterschied von Rad und Rat kann man nicht hören. Um [15]____, ob Kinder richtig schreiben, gibt es Rechtschreib-Tests, bei denen die Kinder nur ein paar Sätze schreiben und Wörter [16]____ ohne Zeitdruck.\n\nDas [17]____ ein wenig der Art, wie Texte in der Erwachsenenwelt entstehen: Manuskripte für Bücher [18]____ in einem gesonderten Schritt Korrektur gelesen. [19]____ darf man nicht außer Acht lassen, dass es auch in der Pädagogik Moden gibt.\n\nVor [20]____ wurde Rechtschreibung in der Schule immens wichtig genommen, [21]____ in den 80er Jahren das Textschreiben wichtiger war. Erst vor etwa 15, 20 Jahren erkannten Forscher, [22]____ Kinder Rechtschreiben lernen und dass wir Rechtschreibung von Anfang an [23]____ müssen.",
