    "article": "Raucher denken weniger flexibel, sie reagieren schwächer auf alternative Handlungszenarien. Genau diese Erkenntnis erklärt, warum es Rauchern oftmals so schwerfällt, von ihrer Sucht [1]____. Dies sind [2]____ einer neuen Studie [3]____ Hirnforscher. Die Ergebnisse dieser Studie wurden nun auch im Fachmagazin „Nature Neuroscience“ [4]____.\n\nWir wollen hier das Wichtigste [5]____: Süchtige sehen die Welt anders – das ist [6]____ nur eine subjektive Behauptung, sondern nun auch wissenschaftlich belegt. Dabei beeinflusst die Sucht das Verhalten der Betroffenen [7]____ vielfältige Weise. Süchtige lassen sich schwerer sättigen, sie machen exzessiv mit einem Verhalten weiter, wo andere längst [8]____. Das Ziel der Forscher war es, die Sucht der Raucher [9]____.\n\nRauchen verändert die Wahrnehmung – das war bekannt. Beim Rauchen werden Belohnungszentren im Gehirn aktiviert, beim Nichtrauchen fehlt ihm dieser Reiz, was [10]____ zu Schmerzen führen kann. Jetzt entdeckten die Hirnforscher: Raucher lassen sich nicht [11]____ [12]____, was hätte sein können, wenn sie eine andere Entscheidung [13]____, wenn sie zum Beispiel die letzte Zigarette nicht [14]____.\n\nDie Forscher [15]____ Raucher und Nichtraucher an einem Börsenspiel teilnehmen. Die Spieler erhielten jeweils 100 Dollar, die sie investieren konnten. Nach jedem Spielzug [16]____ die Spieler, wie sie mehr Geld hätten gewinnen können. Am Ende [17]____ Raucher und Nichtraucher zwar gleich gut ab, doch sie [18]____ unterschiedliche Spielstrategien.\n\nNichtraucher änderten oft ihre Spielweise, sobald sie erfuhren, dass sie in der Vergangenheit mit einer [19]____ Strategie mehr Geld gewonnen hätten. Raucher dagegen [20]____ dem keine Beachtung und spielten weiter, als ob sie diese Information nicht hätten. Die Forscher führen dies auf eine Unfähigkeit der Raucher [21]____, auf alternative Szenarien zu reagieren.\n\nUm den Unterschied zu erklären, wurde während des Versuchs auch [22]____ die Gehirnaktivität der Probanden aufgezeichnet und anschließend untersucht. Dabei stellten sie keine Unterschiede zwischen Rauchern und Nichtrauchern fest und leiteten [23]____ ab, dass Raucher mit denselben Informationen anders umgehen als Nichtraucher. Raucher [24]____ sie einfach. Dies kann auch das Aufhören selbst [25]____: Für Raucher ist es schwerer, die Vorteile des Nichtrauchens zu erkennen.",
