    "article": "Biologen und Schlafforscher sind sich seit Jahren weitgehend einig, dass der Biorhythmus sich umso mehr nach hinten verschiebt, je älter Kinder werden. Etwa im Alter zwischen zwölf und vierzehn Jahren werden die meisten Kinder „Abendtypen“. Ihr erstes Leistungshoch erleben sie am späten Vormittag oder mittags, das zweite nachmittags oder [1]____ erst abends.\n\nSie schlafen erst spät ein und haben frühmorgens die größten Schwierigkeiten aufzustehen. Die Schulen [2]____ auf diese chronobiologischen Rhythmen keine Rücksicht.\n\nTill Ronneburg vom Zentrum für Chronobiologie der Münchner Ludwig-Maximilians-Universität unterscheidet zwischen „Lerchen“, die als Frühaufsteher sehr gut mit der Organisation des Schulalltags [3]____, und „Eulen“. [4]____ sind gezwungen, Tag für Tag früh aufzustehen, obwohl ihre innere Uhr ganz anders [5]____.\n\nIhr Inneres [6]____ noch auf Mitternacht programmiert, wenn der Schulunterricht beginnt, sagt Ronneburg. So stelle der Schulbeginn um acht Uhr morgens eine echte biologische Diskriminierung dar, [7]____ um diese Zeit seien die Spätschläfer bei weitem noch nicht in der Lage, ihre volle Leistung [8]____.\n\nDabei sind sie in der Mehrheit. In einer [9]____ amerikanischen Studie aus dem Jahr 2010 wird ihr Anteil an allen Schülern [10]____ rund 70 Prozent geschätzt.\n\nUmfangreiche Tests [11]____ beispielsweise, dass Klausuren wesentlich besser ausfielen, wenn sie zu einem späteren Zeitpunkt geschrieben wurden. Nun gibt es Stimmen, die auch für deutsche Schüler einen späteren Unterrichtsbeginn [12]____.\n\nDies trifft jedoch nicht [13]____ uneingeschränkte Zustimmung. An einem Münchner Gymnasium wird hierzu ein zweijähriges Pilotprojekt durchgeführt.\n\nBei einer ersten Umfrage [14]____ Schüler an, dass sie den späten Unterrichtsbeginn nicht richtig ausnutzen könnten, weil sie das Haus [15]____ zusammen mit Eltern und Geschwistern relativ früh verlassen müssten.\n\nFür viele sei jedoch die Tatsache von großer Bedeutung, dass der Unterricht zwar erst um 8:30 Uhr beginne, die Schule ihre Tore aber [16]____ um sieben Uhr öffne.\n\nEin Großteil der Schüler schätzt diese Möglichkeit [17]____ offenen Anfangs. Manche [18]____ ihre Schule als Lebensraum, in dem sie Freunde treffen, andere kommen früher, [19]____ ihre Hausaufgaben zu vervollständigen.\n\nBleibt die Frage, ob [20]____ dieser Praxis der späte Unterricht überhaupt den [21]____ nach sich zieht, den sich die Wissenschaftler davon erhoffen.\n\nManche Schüler, die so früh kommen müssten, seien ohnehin schon wach, die anderen aber hätten Zeit, in der Schule „wach zu werden“, [22]____ eine mögliche Antwort.",
