    "article": "Die historischen Wurzeln der kommerziellen Werbung reichen weiter zurück, als es die meisten wohl vermuten würden: Schon im alten Ägypten [1]____ Marktschreier lautstark ihre Waren an und das Werbeplakat findet einen frühen [2]____ in den steinernen Tafeln, auf die Händler ihr Warenangebot meißelten.\n\nIm großen Stil [3]____ konnten die Verkäufer ihre Werbung damals jedoch noch nicht. Erst mit der Erfindung des Buchdrucks Mitte des 15. Jahrhunderts begann die Werbung endgültig ihren Siegeszug.\n\nMit Gutenbergs beweglichen Lettern eröffneten sich ganz neue Möglichkeiten: Erste Handzettel wurden auf dem Marktplatz [4]____ und informierten über die Waren, die die Händler [5]____.\n\nDie Geschichte der Werbung ist also insofern auch eine Geschichte der Kommunikationsmedien, [6]____ diese zwingend notwendig für deren [7]____ waren.\n\nAls 1650 in Leipzig die erste Tageszeitung der Welt herauskam, schien das passende Medium gefunden. Bald schon etablierten sich auch spezielle Werbezeitungen, in die Händler [8]____ Bezahlung ihre Waren eintragen lassen konnten.\n\nEine weitere Erfindung [9]____ der Werbebranche im 19. Jahrhundert einen gewaltigen Schub: Die [10]____ dem Berliner Drucker Ernst Litfaß benannte Litfaßsäule [11]____ von 1855 an nahezu die ganze Welt.\n\n[12]____ gewann Werbung zu dieser Zeit immer mehr an Bedeutung. In einigen Großstädten bestanden die Tageszeitungen sogar bis [13]____ 80 Prozent aus Werbung. Nie zuvor hatte man so viele Kunden erreichen können.\n\nGleichzeitig wurden neue Werbestrategien [14]____ und gezielt bestimmte soziale Schichten angesprochen — heute spricht man von Zielgruppenwerbung.\n\nNachdem Produkte früher nur in [15]____ Bildern dargestellt worden waren, versuchten die Firmen nun, den Konsumenten [16]____, dass ihr Angebot für ihn unverzichtbar sei.\n\nNachdem Werbefilme anfangs nur im Kino gezeigt worden waren, flimmerte 1941 in den USA [17]____ Werbespot über den heimischen Bildschirm — eine Uhrenwerbung.\n\nWährend des Wirtschaftswunders hielt Werbung dank des neuen Mediums auch [18]____ in die deutschen Wohnzimmer: Am 3. November 1956 lief der erste Werbespot im Deutschen Fernsehen.\n\nZuvor hatte es jedoch starken [19]____ gegeben. Kritiker hatten die Befürchtung geäußert, durch Werbung [20]____ das Niveau der Programme absinken.\n\nHeute begegnet man Werbung [21]____. Seit 1994 das erste Werbebanner im Internet aufpoppte, dringt sie auch in die Online-Welt vor. Doch [22]____ ist ihre Geschichte sicher noch nicht beendet.",
