    "article": "Wettbewerb ist die Grundvoraussetzung für die Evolution. Die zum Überleben notwendigen [1]____ sind [2]____, weshalb die Anzahl der Lebewesen nicht [3]____ zunehmen kann.\n\nEin Beispiel: Wenn es [4]____ Nahrung gibt, vermehren sich die Individuen so lange, bis die lebenserhaltende Nahrung [5]____ geht. In der [6]____ [7]____ Konkurrenz. Richtig? Zumindest [8]____.\n\nTatsächlich scheint das Prinzip Konkurrenz [9]____. Das Wetteifern um Nahrung sei nur eine [10]____ des Konkurrenzmechanismus, meint Julia Ostner, Verhaltensbiologin am Johann-Friedrich-Blumenbach-Institut für Zoologie und Anthropologie in Göttingen.\n\nIm [11]____ kann auch um Paarungspartner konkurriert werden oder um einen sicheren Schlafplatz. In dem Moment, in dem wir an Evolution denken, müssen wir Konkurrenz in Betracht [12]____.\n\nDennoch wird die Evolution laut dem Biologen Martin Nowak nicht nur von Konkurrenz und Egoismus [13]____. Als ebenso wichtig im Kampf um das Dasein erweise sich [14]____ Kooperation, so Nowak in der Zeitschrift Spektrum der Wissenschaft.\n\nKonkurrenz allein funktioniert nicht. Zahlreiche Tiere arbeiten zusammen, um besser leben zu können. Durch die gemeinsame Sprache und zunehmend effektivere Kommunikationsmittel [15]____ Kooperation unter Menschen einen höheren Grad [16]____ als unter Tieren, so Biologin Ostner.\n\nSchon in jungen Jahren unterstützen sich Menschen [17]____. Der Mensch sei sogar Weltmeister der Kooperation. Zwischen Konkurrenz und Kooperation [18]____ eine Wechselwirkung.\n\n„Menschen kooperieren, um besser zu konkurrieren“, legt Ostner [19]____. Wenn sich Gruppen von Menschen früher zusammengeschlossen hätten, um ein größeres [20]____ zu bewohnen, dann hätten sie einerseits kooperatives Verhalten, andererseits auch anderen Gruppen gegenüber Konkurrenzdenken gezeigt.\n\nKooperation basiere immer auf Eigennutz. Ein vollkommen selbstloses Agieren gebe es laut der Wissenschaftlerin nicht. Der Ökonom Peter Weise [21]____ zwar zwischen egoistischer Konkurrenz einerseits und altruistischer Konkurrenz andererseits.\n\nDoch sein Fazit ist unmissverständlich: Konkurrenz, egal in welcher Form, [22]____ immer. In der egoistischen Ausprägung [23]____ der Mensch selbst Nutzen aus der Konkurrenz, bei der kollektiven Form handle es sich um eine [24]____ Konkurrenz, bei der ganze Gruppen gegen andere kämpfen.\n\nIn der Geschichte der Menschheit habe solche Konkurrenz nämlich stets negative [25]____ gehabt: Sie habe zu Krieg und Destruktion geführt. Die Natur hat Konkurrenz als Selbsterhaltungsprinzip vorgesehen. Demgegenüber steht die kulturelle [26]____ der Kooperation. Um gut zu leben, müssen wir einen Ausgleich zwischen beiden schaffen.",
