    "teil": 7,
    "title": "Wie kommen Hochs und Tiefs zu ihren Namen / Wetterphänomene und ihre Namen",
    "sourceText": "PDF Baustein Teil 7, S.148-151",
    "mode": "baustein-article",
    "article": "Während die Sturmtiefs Karl und Günther im letzten Frühjahr für zahlreiche entwurzelte Bäume und blockierte Straßen sorgten, [1]____ uns Hoch Lisa einen überdurchschnittlich [2]____ Spätsommer.\n\nWetterereignissen Namen zu geben hat eine lange Tradition. [3]____ Zweiten Weltkrieg begann der US-Wetterdienst, Taifune im Pazifik mit weiblichen Vornamen zu benennen, um sie besonders, wenn mehrere Taifune [4]____ auftraten, besser [5]____.\n\nIn Deutschland vergibt die Freie Universität Berlin die Namen für alle Hoch- und Tiefdruckgebiete, die das Wetter in Mitteleuropa [6]____.\n\n1954 regte die damalige Studentin und spätere ZDF-Wettermoderatorin Karla Wege an, die Druckgebiete zu benennen, um sie leichter [7]____ abzugrenzen. Dafür erstellten die Meteorologen zunächst Listen, [8]____ die Namen in alphabetischer Reihenfolge [9]____: männliche Namen für Hochs, weibliche für Tiefs.\n\nIn den folgenden Jahrzehnten war diese Praxis der Namensvergabe [10]____ die Stadtgrenzen Berlins hinaus bekannt. Erst im Februar 1990, als ungewöhnlich viele und heftige Stürme über Deutschland [11]____, wurden die Medien durch die Orkantiefs „Vivian“ und „Wiebke“ auf die Namensgebung aufmerksam.\n\nSeitdem [12]____ die Verbreitung der von der FU Berlin getauften Druckgebilde und [13]____ Verwendung in den Medien zum Standard.\n\n[14]____, dass Frauennamen ursprünglich immer mit Tiefdruckgebieten in Verbindung [15]____ wurden, kam Ende der 90er Jahre eine hitzige Diskussion über die Vergaberegeln wegen einer möglichen Diskriminierung von Frauen [16]____.\n\nDer Streit konnte jedoch bald beigelegt [17]____, indem [18]____ in Absprache mit dem Deutschen Wetterdienst auf einen jährlich wechselnden Turnus einigte. Seither erhalten die Hochs und Tiefs abwechselnd weibliche und männliche Vornamen.\n\nIm November 2002 wurde schließlich die Aktion Wetterpate [19]____, die bis heute existiert. Wer gerne eine Patenschaft übernehmen oder verschenken möchte, kann dies [20]____ festgelegten Termin, der auf Ende September oder Anfang Oktober des Vorjahres fällt, bei der FU Berlin beantragen.\n\nDer Preis dafür hängt von der persönlichen Vorliebe ab: Die Patenschaft für eines der [21]____ Hochdruckgebiete kostet mehr als diejenige für ein Tief. Die vergebenen Namen werden allen Wetterdiensten und Medien [22]____. Neben dem US-Wetterdienst ist die Freie Universität Berlin weltweit die einzige Institution, die Namen für Hoch- und Tiefdruckgebiete vergibt.",
