    "article": "Studierende der Geisteswissenschaften werden oft [1]____, was sie nach ihrem Studium beruflich einmal machen wollen. Da lohnt sich die Frage, wo denn [2]____ heute arbeiten, die Seminare, Vorlesungen und Prüfungen bereits erfolgreich [3]____ sich gelassen haben.\n\nÜber das Programm „Ein Tag mit“ können Studierende einen [4]____ in das Arbeitsleben von Alumni ihres Studienganges bekommen. „Es hat mir viel Mut [5]____ zu sehen, dass ich mit meinem Studiengang auf jeden Fall genug Kompetenzen [6]____ habe, um nach meinem Abschluss einen Job zu bekommen“, erzählt Vivienne, die im vierten Master-Semester Anglistik studiert.\n\nSie hat [7]____ Rahmen von „Ein Tag mit“ der Anglistik-Alumni Magdalena Kaminska bei ihrer Arbeit als [8]____ Coach im Wissenschaftsbereich über die Schulter geschaut. [9]____ wurden beide durch die Mentorinnen der Philologischen Fakultät und das zentrale Alumni-Büro der Universität Leipzig.\n\n„Es ist uns wichtig zu zeigen, wie [10]____ das Berufsangebot mit einem Studium der Geistes- und Sozialwissenschaften ist. Wenn man zum Beispiel Germanistik studiert, kommen nicht nur Verlagsarbeit oder Journalismus [11]____. Den Blick der Studierenden für andere [12]____ Bereiche zu öffnen, sehen wir als ersten wichtigen [13]____ für die eigene Zukunftsplanung“, erklärt Julia Protze, [14]____ an der Philologischen Fakultät.\n\nFranziska, Musterstudentin der Germanistik, war [15]____ ihrem Tag in der Stadtverwaltung Guben im Sachgebiet Öffentlichkeitsarbeit begeistert. „Ich fühle mich nun ein wenig sicherer in meinem [16]____, in die Öffentlichkeitsarbeit zu gehen. Susanne Winter hat das Gleiche studiert wie ich und mir meine Fragen ausführlich beantwortet. Außerdem [17]____ ich live miterleben, wie sie einem TV-Team spontan eine Stellungnahme gegeben hat und konnte so gleich einmal sehen, was die Arbeit einer Pressesprecherin alles beinhalten kann.“\n\nGermanistik-Student David war [18]____ [19]____ an der Bucerius Law School in Hamburg: „Meine Erwartungen wurden definitiv erfüllt. Ich konnte ein paar ehrliche Einschätzungen bekommen“, berichtet er [20]____ [21]____ [22]____ seinem Tag mit Alumni Dr. Annette Bärwi.\n\nAuch die am Projekt [23]____ Alumni empfinden den Tag mit den [24]____ [25]____ Bereicherung. Bereits 25 Alumni aus verschiedenen [26]____ konnten seit dem Projektbeginn für das Programm gewonnen werden. Einige von ihnen hatten schon [27]____ Besuch von einem Studenten oder einer Studentin ihrer Fachrichtung.",
