    "article": "Wer etwas kaufen will, braucht Geld und bekommt dafür Waren oder Dienstleistungen — dieser Vorgang könnte einfacher [1]____ sein.\n\nDie Geschäfte, die unsere Vorfahren vor Jahrtausenden [2]____, waren deutlich komplizierter. Sie [3]____ direkten Warentausch, das heißt: Sie tauschten Waren aus, ohne dass Geld [4]____. Die Sache hatte allerdings einen Haken: Brauchte etwa der Bauer ein Fell vom Jäger, dieser aber gerade kein Getreide, geriet das System aus dem [5]____.\n\nUm dieses umständliche Vorgehen zu [6]____, wurde ein Tauschmittel erfunden, das alle Käufer und Verkäufer [7]____: Natural- oder Warengeld, also nützliche und wertvolle Güter, die als allgemeines Zahlungsmittel [8]____. Dabei benutzte man im Laufe der Zeit die unterschiedlichsten Dinge — etwa Muscheln, Steinscheiben, Salz, Felle, Edelsteine oder auch [9]____. Es wird vermutet, dass diese Geldvorläufer schon [10]____ 6.000 Jahren eingesetzt wurden.\n\nDie ersten Münzen wurden im 7. Jahrhundert v. Chr. in dem antiken Königreich Lydien geprägt. Diese erleichterten den Handel [11]____. Im Lauf der Jahrhunderte verbreitete sich das Münzgeld im antiken Mittelmeerraum und gelangte schließlich ins restliche Europa.\n\nDas nächste Kapitel in der Geschichte des Geldes wurde im 11. Jahrhundert in China [12]____. Als [13]____ für Münzgeld entstand Papiergeld. In Europa wurde es jedoch viel später eingeführt; es kam erst im 15. Jahrhundert in Spanien auf. Dass es sich [14]____ als Alternative zum Münzgeld durchsetzte, ist wohl seinen deutlich [15]____ Vorteilen geschuldet: Es wog wenig und war einfach herzustellen.\n\nDoch [16]____ war die Geschichte des Geldes nicht zu Ende: Eine weitere [17]____ war das ab dem 14. Jahrhundert aufkommende immaterielle Geld, das sogenannte Giralgeld. Im Laufe des 20. Jahrhunderts entwickelte sich der bargeldlose Zahlungsverkehr zu einem Standard. In Zeiten des Internets kamen [18]____ Online-Zahlungssysteme und das Online-Banking auf. Auch wenn heute noch fast jeder ein paar Geldscheine im Portemonnaie hat, ist oft davon [19]____, dass die Tage des Bargelds gezählt [20]____. Möglicherweise ist sein Ende also absehbar.",
