    "article": "Es ist so etwas, was einfach so passiert. Jeder Mensch macht es, wenn er auf die Welt kommt, er kann nicht [1]____: Er fängt an zu spielen. Auch wenn es nicht immer [2]____ aussieht. Mit den Beinen zu strampeln, nach einem Gegenstand zu greifen, Geräusche zu fabrizieren — all das sind Spiele, die dazu dienen, dass ein Kind sich ausprobiert, seine Welt entdeckt und lernt, darin [3]____.\n\nWenn ein Kind [4]____ seinen Löffel aus dem Hochstuhl fallen [5]____, macht es das nicht, um die Eltern zu ärgern, sondern um Dinge herauszufinden und diese abzuspeichern: Kann man den [6]____ hören? Wie lange dauert es, bis man ihn hört? Oder geht der Gegenstand sogar dabei kaputt?\n\nTrotzdem halten viele Erwachsene Spielen für etwas, was Kinder zum [7]____ machen, was aber wenig produktiv ist. Dabei ist Spielen in jedem Alter die Grundlage von allem, was man für den Rest [8]____ Lebens braucht. Menschenkinder müssen, wie übrigens auch Tiere, durch eigene Erfahrungen lernen. Sie beobachten und probieren [9]____, wie man sich Nahrung sucht, wie man sich vor Gefahren schützt und wie man in der Gemeinschaft lebt. Die Struktur des Gehirns wird während der Kindheit dadurch geformt, [10]____ es Dinge bewältigt und Erfahrungen sammelt. Nebenbei wird auch das Selbstvertrauen [11]____.\n\nUm fit fürs Leben zu werden, [12]____ es also Freiräume, in denen Kinder sich selbst ausprobieren können. Beides ist wichtig: einerseits allein zu spielen, denn das [13]____ Konzentration und Kreativität. Aber andererseits auch das Spielen mit anderen Kindern, die [14]____ auch älter sein dürfen, denn dann kann man [15]____ etwas abschauen.\n\nAuch das Rollenspiel ist für die Entwicklung wichtig, ist es [16]____ eine Art soziales und emotionales Training. [17]____ die Rolle eines anderen zu schlüpfen bedeutet vor allem, sich [18]____ in eine andere Stimmung zu versetzen. So kann man Ängste, Trauer und Wut besser verarbeiten und [19]____ gleichzeitig Einfühlungsvermögen für andere.\n\nDa das alles wichtig ist, steht das Recht [20]____ spielen auch im Artikel 31 Absatz 1 der UN-Kinderrechtskonvention. Eltern, die trotzdem noch [21]____ sind, sollten bedenken: Spielen ist die Arbeit der Kinder, und jede Arbeit muss [22]____ werden.",
