    "article": "Gespielt wird überall. Aber Spiele sind durchaus kein sinnloser [1]____, sondern Quelle menschlicher Kreativität. Ohne Spiel entsteht keine Kultur: Für den niederländischen Kulturhistoriker Johan Huizinga [2]____ sich der Mensch nicht nur durch seine Vernunft und sein Schaffen aus, sondern auch durch sein Spiel. Schon immer haben sich Spiele an die Eigenheiten ihrer [3]____ Zeit angepasst. In virtuellen Welten kommen Spieler auf der ganzen Welt zusammen, um Städte zu bauen, Monster zu bekämpfen, Strategien zu entwickeln und in andere Rollen zu [4]____.\n\nDie große Beliebtheit von Computerspielen führt dazu, dass [5]____ Mechanismen und Prinzipien sich mehr und mehr auch in der realen Welt [6]____: Punkte sammeln, Highscores [7]____ und in höhere Levels vorstoßen – das gehört längst zum Alltag, und zwar auch jenseits digitaler Spiele. Der Begriff „Gamification“ – [8]____ von dem Programmierer Nick Pelling – ist mittlerweile in aller [9]____. Er bezeichnet die [10]____ von Spielmechanismen auf nicht-spielerische – etwa didaktische – Kontexte.\n\nDabei macht Gamification es sich zum Ziel, den dem Menschen [11]____ Spieltrieb zu aktivieren, um so die Motivation [12]____ bei unbeliebten Aufgaben und Themenstellungen zu erhöhen. Spielerisch lernen und dabei die neuesten digitalen Entwicklungen nutzen – wer [13]____ denn nicht an diesem Trend teilhaben? In das Bildungswesen hat die Gamification jedenfalls schon längst Einzug [14]____. Dabei geht es aber nicht nur um simple, [15]____ Lernspiele, sondern auch um durchaus vielschichtige Spielanordnungen.\n\nDiese werden zum Beispiel in Veranstaltungen an Hochschulen eingesetzt. So können etwa Mathematik-Studenten durch [16]____ Lösen von Aufgaben auf der Lernplattform Punkte gewinnen, oder Studienanfänger begeben sich auf eine virtuelle Forschungsreise in die Antarktis, um Fähigkeiten wie [17]____, Zitieren oder wissenschaftliches Schreiben einzuüben. Kritiker [18]____ zwar, dass man [19]____ Lernen und Bearbeiten schwieriger Sachverhalte nicht durch Spaß und Spannung ersetzen könne.\n\nAndererseits scheinen aber die für Wissensvermittlung verwendeten spielerischen Elemente bei [20]____ Betrachtung einen wertvollen [21]____ zu leisten. Denn Spiele stellen ihre Teilnehmer [22]____ vor äußerst komplexe Herausforderungen – und wecken so den Drang, diese durch noch mehr Wissensaneignung und Kooperation zu meistern.",
