    "article": "Alle Gäste sitzen gemeinsam an einem langen Tisch und es gibt nur [1]____ ein Menü: So [2]____ man in einem Sternerestaurant in Hamburg, und für so manchen [3]____ ist dies der letzte [4]____. Dass dieses Konzept neu ist, lässt [5]____ jedoch nicht behaupten.\n\nDenn bis ins 19. Jahrhundert hinein war dies unter europäischen Adligen genauso [6]____. Zu einer [7]____ Essenszeit setzten sich die Herrschaften gemeinsam an den Tisch des Gastgebers. [8]____ französisch serviert, trug das Personal alle [9]____ gleichzeitig auf; wurde russisch serviert, brachte man diese einzeln an den Tisch. Auch Wirtshäusern und Gaststätten war eine freie Menüwahl unbekannt. [10]____ essen gehen wollte, bekam ein Tagesmenü [11]____ Festpreis. Was es daher nicht gab, waren eine Speisekarte und Einzeltische. Denn die moderne Restaurantkultur, [12]____ heute kennen, war noch nicht erfunden.\n\nWann das erste Restaurant eröffnet wurde, ist zwar unbekannt, aber es [13]____ einiges darauf hin, dass dies in Paris geschah. Und der erste Spitzenkoch kam – keine Überraschung – ebenfalls aus Paris. Es handelt sich dabei um Marie-Antoine Carême, der zur Zeit Napoleons am französischen Hof wirkte und einer der bedeutendsten Köche seiner Zeit war. Von ihm sind Kochbücher und zahlreiche Rezepte [14]____.\n\nDass es für uns alltäglich ist, in Restaurants zu essen, haben wir [15]____ der Französischen Revolution zu [16]____. Köche und Küchenpersonal [17]____ sich nach dem Sturz des Adels ein neues Betätigungsfeld suchen – und fanden in dem [18]____ Bürgertum ein hungriges Publikum. In dieser Zeit änderten [19]____ auch die geschmacklichen Vorlieben. Das Essen wurde pikanter, und die Gäste legten mehr [20]____ auf den Eigengeschmack der Zutaten.\n\nDamals wurde eine Zutat erfunden, die heute in keiner Küche fehlt: die Bouillon, eine stark konzentrierte Fleischbrühe, die [21]____ Grundlage für Suppen und Soßen dient. In der ersten Hälfte des 19. Jahrhunderts nahm die Zahl der Restaurants stark zu und es [22]____ sich eine bürgerliche Esskultur, bei der der Genuss im Vordergrund stand. Restaurantbesuche wurden zum Ausdruck des Lebensstils – und sind es bis heute geblieben.",
