    "article": "Die [1]____ nach einem grundlegenden System hinter den Dingen stellten [2]____ bereits die [3]____ des Altertums. Schon sie erkannten, dass sich einige Stoffe stärker ähnelten als andere, [4]____ versuchten, darin eine Ordnung zu erkennen. [5]____ entscheidende Durchbruch aber gelang erst viele Jahrhunderte später dem russischen Chemiker Dmitri Mendelejew.\n\nEr ordnete die bekannten chemischen Elemente [6]____ [7]____ Eigenschaften und Atomgewichten und erkannte die [8]____ Gesetzmäßigkeiten. [9]____ heute hat sich das Periodensystem des russischen Chemikers als unverwüstlich [10]____: Alle Fortschritte der Chemie und Atomphysik haben die geniale Entdeckung Mendelejews [11]____ und erweitert.\n\nIm September 1860 wurde in Karlsruhe der erste internationale chemische Kongress eröffnet, der Kongress, der [12]____ machen musste. Denn er erwies sich [13]____ [14]____ für [15]____ bedeutendsten Fortschritte der modernen Chemie. Mendelejew [16]____ daran teil. Schon seit einigen Jahren hatte ihn die Frage nach einer [17]____ der rund 60 bekannten Elemente beschäftigt. Die Initialzündung für Mendelejew [18]____ ein Vorschlag seines italienischen Kollegen Stanislao Cannizzaro zur Bestimmung des [19]____ von Molekülen.\n\n„Wenn man nach etwas sucht, [20]____ es Pilze oder eine Art von Gesetz, [21]____ es keinen Weg, als immer wieder zu schauen und erneut zu versuchen“, so beschrieb Mendelejew [22]____ Bemühungen [23]____ ein Ordnungssystem der Elemente.\n\nAm 06. März 1869 veröffentlichte Mendelejew sein Periodensystem unter dem Titel „Die Abhängigkeit [24]____ chemischen Eigenschaften der Elemente vom Atomgewicht“. Darin bilden die Elemente Gruppen, die jeweils senkrecht untereinander Stoffe mit ähnlichen Eigenschaften vereinen. Gruppen sind wiederum horizontal so angeordnet, dass in den Zeilen, den sogenannten [25]____ des Systems, die Atommassen und Valenzen der Elemente aufsteigen.\n\n[26]____ störten einige Ausreißer das Bild. Mendelejew war jedoch so überzeugt von seinem System, dass er für solche Ausreißer nur eine einzige Erklärung sah: Ihr Atomgewicht musste falsch bestimmt worden sein. Kurzerhand verschob er einige Elemente [27]____ andere Stellen. [28]____ noch etwas, was seinen Kollegen geradezu unerhört erschien: Er ließ an einigen Stellen [29]____ Periodensystem Lücken, weil seiner Ansicht nach hier Elemente hingehörten, die [30]____ existierten, aber noch nicht entdeckt worden waren. Für Mendelejew war klar, dass sein [31]____ die fundamentale Ordnung der Elemente widerspiegelte – die Grundlage des gesamten [32]____.",
