    "mode": "baustein-article",
    "article": "Mit rasender Geschwindigkeit haben neue Informations- und Kommunikationstechnologien die Welt des Studiums in einem Jahrzehnt komplett verändert. Das Internet bietet heute unvorstellbare Möglichkeiten, orts- und zeitunabhängig [1]____ Sekundenschnelle universitäre Lehrprogramme, Studiengänge und akademische Bildungsangebote zu nutzen.\n\nPerfekt durchstrukturierte Online-Vorlesungen, elektronisch [2]____ Lehrvideos in Tonqualität, Foliensätze, Übungsaufgaben und Testfragen mit Musterantworten sind mühelos und [3]____ abrufbar. Cross- und multimediale Zusatzangebote aus Mediatheken, Hintergrundmaterialien, [4]____ Datenbanken, Quellen und weiterführende Literatur gehören [5]____ dazu wie Case Studies aus der Praxis, Anwendungsbeispiele, Chatrooms, Netzwerke, interaktive Foren, Seminare und Tutorien.\n\nDas „Studium virtuale“ ermöglicht täglich, an Wochenenden und Feiertagen, rund um die Uhr Zugang zum Wissen der klügsten Gelehrten und zu [6]____ feinsten und besten Ideen.\n\nWer braucht [7]____ so exzellenten Online-Studienbedingungen noch Lehrveranstaltungen, die zu fixen Zeiten an festen Orten [8]____ werden von Professoren, deren Interesse an der Lehre zweitrangig ist oder deren pädagogische Fähigkeiten niemals wirklich [9]____ wurden?\n\nWieso sollen Studierende noch in [10]____ Hörsälen sitzen, [11]____ sie von zu Hause aus oder von wo und wann [12]____ Vorlesungen von den weltweit besten, hoch motivierten und [13]____ bestens geschulten Professoren besuchen können, [14]____ mit den modernsten Hilfsmitteln?\n\nWie eine Flutwelle wird [15]____ die Lehre aus dem Hörsaal heraus und [16]____ ins Internet stürzen, [17]____ auch, weil das „Studium virtuale“ dem Verhalten junger Menschen und ihren Erfahrungen mit neuen Medien [18]____.\n\nDie jüngere Generation erwerbe sich [19]____ immer weniger durch Lesen oder Hören, sondern immer stärker durch Schauen und Klicken. Was nicht visualisiert und verlinkt [20]____, finde nur schwer Aufmerksamkeit und Interesse, so Beobachter.\n\nMan kann das Aussterben [21]____ [22]____. Korrigieren wird sich die Verlagerung des Studiums ins Internet kaum mehr [23]____. Sie wird von hinten nach vorne das Wesen der universitären Ausbildung umpflügen.\n\n[24]____ werden die oft berufsbegleitenden und vermehrt interdisziplinären Angebote für Zweitstudien, Nachdiplom- oder Zusatzstudiengänge online gehen, die [25]____ von Wiedereinsteigern und Umsteigern nachgefragt werden. Später werden die Doktoranden- und Masterprogramme folgen. Schlussendlich werden auch mehr und mehr Bachelorstudiengänge als Fernstudium angeboten werden.",
