    "title": "Wenn Wörter verschwinden",
    "sourceText": "PDF Baustein 1303新更 Teil 19, S.172-173",
    "mode": "baustein-article",
    "article": "Was ist das für ein hanebüchener Kokolores, treibt da ein Schlingel Schabernack? - So redet heute wohl niemand mehr. Manch einer mag über die alten Wörter abfällig den Kopf [1]____, bei manch einem wecken sie nostalgische Gefühle, und manch ein jüngerer Mensch hat diese [2]____ noch nie gehört.\n\nIm Laufe der Jahre verschwinden immer wieder Wörter aus dem aktiven [3]____. »Der Grund dafür ist eigentlich ganz [4]____«, sagt Claudia Wich-Reif, Professorin für Geschichte der deutschen Sprache an der Universität Bonn: »Wir brauchen diese Wörter nicht mehr.«\n\nDafür gibt es unterschiedliche Ursachen. Häufig werden Begriffe durch modernere - oft aus dem Englischen [5]____ Bezeichnungen ersetzt, zum Beispiel »High Heels« statt »Stöckelschuh«. [6]____ Wörter werden abgelöst, weil sie heute etwa als [7]____ gelten.\n\nManchmal verschwinden Wörter auch, weil es die Sache, die sie bezeichnen, [8]____ noch gibt - etwa »Walkman«. Es seien [9]____ nur sehr alte Wörter vom Aussterben bedroht, sondern durchaus auch relativ junge Begriffe, die schlichtweg vom Fortschritt [10]____ würden, sagt Wich-Reif.\n\n»Durch das [11]____ von Wörtern verarmt die Sprache aber nicht«, [12]____ die Sprachwissenschaftlerin. »Wir bekommen ja auch ständig neue Wörter dazu.« Viele davon kämen aus der [13]____.\n\nKatharina Mahrenholtz hat 100 »vergessene Wörter« in einem im Duden-Verlag erschienenen Buch [14]____ und ihre Herkunft [15]____. »Kaum jemand kennt zum Beispiel die ursprüngliche Bedeutung von ›hanebüchen‹.« »Kokolores« entstand laut Mahrenholtz wahrscheinlich im 16. Jahrhundert als [16]____ eines Hahnenschreis, so wie »Kikeriki«. »Kokolores« ist als [17]____ für »Unsinn« oder »Quatsch« inzwischen eher ungebräuchlich, ähnlich wie »Firlefanz«, »Mumpitz« oder auch »Schabernack«. »Ich mag diese Wörter. Sie [18]____ schon vom Klang her eine gewisse Lustigkeit«, meint Mahrenholtz.\n\nDeshalb verwende sie sie auch manchmal noch - genauso wie einige andere, die sie [19]____ persönlichen Erinnerungen verbinde. »Schlingel« zum Beispiel habe ihre Oma immer gesagt. Kindheitserinnerungen und Nostalgie [20]____ häufig Gründe, warum jemand ein inzwischen ungebräuchliches Wort weiterbenutzt - oder weil er bedauere, dass es kaum noch zu hören sei, sagt auch Wich-Reif. Allerdings: »Die Wörter sind ja nicht wirklich weg, sondern existieren in alten Texten [21]____«, sagt die Wissenschaftlerin. »Sprache [22]____ dem Wandel und ist immer auch ein Kennzeichen für eine bestimmte Zeit.«",
